import { useCallback, useMemo } from 'react';
import { FormattedMessage, useIntl } from 'react-intl';

import { PageHeader, StickyScrollWithFilters } from 'components';
import {
  StickyNavigationTopOffsetProvider,
  useCurrentPage,
  usePageFilterApplied,
  usePageFilterManagement,
  usePageFilterStatus,
  useRelatedAnalysisContextBanner,
} from 'hooks';
import { BrandPowerContextBanner } from 'pages/pillars/PortfolioBrand/BrandPowerBookExport/components/BrandPowerContextBanner';
import { StyledGridContainer, StyledHomeContainer } from 'shared/Styles';
import { boldRichTextValues } from 'utils/i18n/richTextValues';

import { KpiSwitch } from './components/KpiSwitch/KpiSwitch';
import {
  PERFORMANCE_TOOL_MAX_VISIBLE_FILTERS,
  PERFORMANCE_TOOL_NAVIGATION_TEST_ID,
  PERFORMANCE_TOOL_PAGE_NAME,
  PERFORMANCE_TOOL_VISIBLE_FILTER_FIELDS,
  WATERFALL_RESET_EVENT,
} from './constants';
import { getPageSubtitleByKpi, getPageTitleByKpi } from './utils';

export const PerformanceTool: React.FC = () => {
  const { currentPage } = useCurrentPage();
  const { formatMessage } = useIntl();
  const showRelatedAnalysisBanner =
    useRelatedAnalysisContextBanner('brand-power');

  const { applied } = usePageFilterApplied(currentPage);
  const { isLoading: isFilterLoading } = usePageFilterStatus(currentPage);

  const { updateForm, apply } = usePageFilterManagement(
    PERFORMANCE_TOOL_PAGE_NAME,
  );

  const pageTitle = useMemo(
    () => formatMessage({ id: getPageTitleByKpi(applied.kpis as string) }),
    [applied.kpis, formatMessage],
  );

  const handleFilterChange = (key: string, value: string) => {
    updateForm(key, value);
    apply();
  };

  const handleFilterReset = useCallback(() => {
    globalThis.dispatchEvent(new Event(WATERFALL_RESET_EVENT));
  }, []);

  return (
    <>
      <StickyScrollWithFilters
        filter={{
          pageName: PERFORMANCE_TOOL_PAGE_NAME,
          visibleFields: PERFORMANCE_TOOL_VISIBLE_FILTER_FIELDS,
          maxVisibleFilters: PERFORMANCE_TOOL_MAX_VISIBLE_FILTERS,
          onReset: handleFilterReset,
        }}
        breadcrumbs={{
          pageList: [
            { href: '/value-creation', pageName: 'Value Creation' },
            {
              href: '/value-creation/performance-tool',
              pageName: 'Performance Tool',
            },
          ],
          showIcon: true,
        }}
        isResponsivePage
        dataTestId={PERFORMANCE_TOOL_NAVIGATION_TEST_ID}
      />

      <StickyNavigationTopOffsetProvider
        navigationTestId={PERFORMANCE_TOOL_NAVIGATION_TEST_ID}
      >
        <StyledGridContainer isResponsivePage>
          <StyledHomeContainer>
            <PageHeader
              title={pageTitle}
              subtitle={
                <FormattedMessage
                  id={getPageSubtitleByKpi(applied.kpis as string)}
                  values={
                    boldRichTextValues as unknown as Record<
                      string,
                      React.ReactNode
                    >
                  }
                />
              }
              loading={isFilterLoading}
            />
            {showRelatedAnalysisBanner && (
              <BrandPowerContextBanner
                title={formatMessage({
                  id: 'ValueCreation.PerformanceTool.contextBanner.fromBrandPower.title',
                  defaultMessage:
                    'Performance Tool opened with Brand Power context',
                })}
                message={formatMessage({
                  id: 'ValueCreation.PerformanceTool.contextBanner.fromBrandPower.message',
                  defaultMessage:
                    'Power KPI and current country were preserved to make navigation context clear.',
                })}
                duration={6000}
              />
            )}
            <KpiSwitch
              kpi={applied.kpis as string}
              onFilterChange={handleFilterChange}
            />
          </StyledHomeContainer>
        </StyledGridContainer>
      </StickyNavigationTopOffsetProvider>
    </>
  );
};
